// Generated by OmniLang — React target

import React, { useState, useEffect, useMemo, useRef } from 'react';
import styles from './NotificationsPanel.module.css';

import { useNotificationStore } from './useNotificationStore';

export function NotificationsPanel() {
    const NotificationStore = useNotificationStore();
    const [badgeVisible, setBadgeVisible] = useState(false);
    useEffect(() => {
        if (NotificationStore.unreadCount > 0) {
            setBadgeVisible(true);
        }
    }, [notifications]);

    return (
        <div
            className="panel"
        >
            <div
                className="header"
            >
                <h3
                    className="title"
                >
                    {'Notifications'}
                    {
                        badgeVisible && (
                            <fragment>
                                <span
                                    className="badge"
                                >
                                    {'New'}
                                </span>
                            </fragment>
                        )
                    }
                </h3>
                <div
                    className="header-actions"
                >
                    <button
                        className="btn-sm"
                        onOnPress={(e) => {
        NotificationStore.add("Notification " + NotificationStore.unreadCount.to_string());
      }}
                    >
                        {'Add'}
                    </button>
                    <button
                        className="btn-sm"
                        onOnPress={(e) => {
        NotificationStore.removeLast();
      }}
                    >
                        {'Remove'}
                    </button>
                    <button
                        className="btn-clear"
                        onOnPress={(e) => {
        NotificationStore.clear();
        setBadgeVisible(false);
      }}
                    >
                        {'Clear'}
                    </button>
                </div>
            </div>
            {''}
            <div
                className="slot-header-area"
            >
            </div>
            {''}
            <div
                className="scroll-area"
                data-ref="scrollContainer"
            >
                {
                    NotificationStore.unreadCount === 0 && (
                        <fragment>
                            <p
                                className="empty-text"
                            >
                                {'No notifications'}
                            </p>
                        </fragment>
                    )
                }
                {
                    NotificationStore.notifications.map((item, index) => (
                        <fragment>
                            <div
                                className="notification-item"
                                onOnPress={(e) => {
        setBadgeVisible(false);
      }}
                            >
                                <span
                                    className="dot"
                                />
                                <span
                                    className="item-text"
                                >
                                    {/* interpolation */}
                                </span>
                            </div>
                        </fragment>
                    ))
                }
            </div>
            {''}
            <div
                className="footer"
            >
                <p
                    className="count-text"
                >
                    {'Total:'}
                    {/* interpolation */}
                </p>
                <div
                    className="slot-footer-area"
                >
                </div>
            </div>
        </div>
    );
}

